(function() {
  var _result = {};
  try {
    var comp = app.project.activeItem;
    if (!comp || !(comp instanceof CompItem)) {
      _result = {status:"error", message:"No active comp"};
      return JSON.stringify(_result);
    }
    var p = {
      layerName: ${layerName},
      contrast: ${contrast},
      saturation: ${saturation},
      cyanTint: ${cyanTint},
      magentaTint: ${magentaTint},
      vignetteAmount: ${vignetteAmount}
    };
    var layer = p.layerName ? comp.layers.byName(p.layerName) : comp.layer(1);
    if (!layer) {
      _result = {status:"error", message:"Layer not found"};
      return JSON.stringify(_result);
    }
    var levels = layer.Effects.addProperty("ADBE Levels");
    levels.property("ADBE Levels-0003").setValue(p.contrast / 100 + 1);
    var hs = layer.Effects.addProperty("ADBE Hue/Saturation");
    hs.property("ADBE Hue/Saturation-0003").setValue(p.saturation);
    var cc = layer.Effects.addProperty("ADBE Channel Mixer");
    cc.property("ADBE Channel Mixer-0004").setValue(100 + p.cyanTint);
    cc.property("ADBE Channel Mixer-0005").setValue(100 + p.cyanTint);
    cc.property("ADBE Channel Mixer-0007").setValue(100 + p.magentaTint);
    cc.property("ADBE Channel Mixer-0009").setValue(100 + p.magentaTint);
    var vignette = layer.Effects.addProperty("ADBE Vignette");
    vignette.property("ADBE Vignette-0001").setValue(p.vignetteAmount / 100);
    _result = {status:"success", message:"赛博朋克调色已应用"};
  } catch(e) {
    _result = {status:"error", message:"Error: " + e.toString()};
  }
  return JSON.stringify(_result);
})();

