      _result = {status:"error", message:"No active comp"};
      return JSON.stringify(_result);
    }
    var p = {
      layerName: ${layerName},
      intensity: ${intensity},
      redShift: ${redShift},
      blueShift: ${blueShift},
      contrast: ${contrast},
      saturation: ${saturation}
    };
    var layer = p.layerName ? comp.layers.byName(p.layerName) : comp.layer(1);
    if (!layer) {
      _result = {status:"error", message:"Layer not found"};
      return JSON.stringify(_result);
    }
    var cm = layer.Effects.addProperty("ADBE Channel Mixer");
    cm.property("ADBE Channel Mixer-0001").setValue(100 + p.redShift * p.intensity);
    cm.property("ADBE Channel Mixer-0004").setValue(p.redShift * 0.3 * p.intensity);
    cm.property("ADBE Channel Mixer-0009").setValue(100 + p.blueShift * p.intensity);
    cm.property("ADBE Channel Mixer-0007").setValue(-p.blueShift * 0.3 * p.intensity);
    var hs = layer.Effects.addProperty("ADBE Hue/Saturation");
    hs.property("ADBE Hue/Saturation-0003").setValue(p.saturation * p.intensity);
    var levels = layer.Effects.addProperty("ADBE Levels");
    levels.property("ADBE Levels-0003").setValue(1 + p.contrast * p.intensity / 80);
    _result = {status:"success", message:"红外摄影调色已应用"};
  } catch(e) {
    _result = {status:"error", message:"Error: " + e.toString()};
  }
  return JSON.stringify(_result);
})();
